using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Moq;
using Volo.Abp.Cli.Auth;
using Volo.Abp.Cli.Commands;
using Volo.Abp.Cli.Args;
using Xunit;

namespace Volo.Abp.Cli.Tests.Commands
{
    public class LoginInfoCommandTests
    {
        private class TestLoginInfoCommand : LoginInfoCommand
        {
            public TestLoginInfoCommand(AuthService authService) : base(authService)
            {
            }

            public new AuthService AuthService { get; set; }
        }

        [Fact]
        public async Task ExecuteAsync_LogsInformation_WhenLoggedInAndLoginInfoNotNull()
        {
            // Arrange
            var mockAuthService = new Mock<AuthService>(MockBehavior.Strict, null, null, null, null, null, null);
            var loginInfo = new LoginInfo
            {
                Name = "John",
                Surname = "Doe",
                Username = "johndoe",
                EmailAddress = "john.doe@example.com",
                Organization = "ExampleOrg"
            };

            // Setup static IsLoggedIn method by wrapping in a testable instance method via subclass
            mockAuthService.Setup(a => a.IsLoggedIn()).Returns(true);
            mockAuthService.Setup(a => a.GetLoginInfoAsync()).ReturnsAsync(loginInfo);

            var mockLogger = new Mock<ILogger<LoginInfoCommand>>();

            var command = new TestLoginInfoCommand(mockAuthService.Object)
            {
                Logger = mockLogger.Object,
                AuthService = mockAuthService.Object
            };

            // Act
            await command.ExecuteAsync(new CommandLineArgs());

            // Assert
            mockLogger.Verify(
                x => x.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Login info:") && v.ToString().Contains("John") && v.ToString().Contains("Doe")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }

        [Fact]
        public async Task ExecuteAsync_LogsError_WhenNotLoggedIn()
        {
            // Arrange
            var mockAuthService = new Mock<AuthService>(MockBehavior.Strict, null, null, null, null, null, null);
            mockAuthService.Setup(a => a.IsLoggedIn()).Returns(false);

            var mockLogger = new Mock<ILogger<LoginInfoCommand>>();

            var command = new TestLoginInfoCommand(mockAuthService.Object)
            {
                Logger = mockLogger.Object,
                AuthService = mockAuthService.Object
            };

            // Act
            await command.ExecuteAsync(new CommandLineArgs());

            // Assert
            mockLogger.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("You are not logged in.")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }

        [Fact]
        public async Task ExecuteAsync_LogsError_WhenLoginInfoIsNull()
        {
            // Arrange
            var mockAuthService = new Mock<AuthService>(MockBehavior.Strict, null, null, null, null, null, null);
            mockAuthService.Setup(a => a.IsLoggedIn()).Returns(true);
            mockAuthService.Setup(a => a.GetLoginInfoAsync()).ReturnsAsync((LoginInfo)null);

            var mockLogger = new Mock<ILogger<LoginInfoCommand>>();

            var command = new TestLoginInfoCommand(mockAuthService.Object)
            {
                Logger = mockLogger.Object,
                AuthService = mockAuthService.Object
            };

            // Act
            await command.ExecuteAsync(new CommandLineArgs());

            // Assert
            mockLogger.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Unable to get login info.")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }
    }
}
```

The ExecuteAsync method is not virtual, so I cannot override it in a subclass for testing. Also, the AuthService.IsLoggedIn() is static and cannot be mocked easily.

Given these constraints, I will write tests that call ExecuteAsync as-is, but I will inject a mock ILogger<LoginInfoCommand> and a real or mocked AuthService. Since AuthService.IsLoggedIn() is static and checks a file, I will mock the AuthService.GetLoginInfoAsync() method and rely on the real static IsLoggedIn() method by creating or deleting the file it checks.

Alternatively, I can test only the Logger.LogInformation call by calling a helper method that builds the string and logs it, but no such method exists.

Since the code is not easily testable without refactoring, I will write tests that cover the other branches and verify the Logger calls by mocking ILogger and using a real AuthService with the static IsLoggedIn() method.

I will write a test that:

- Mocks ILogger<LoginInfoCommand>
- Mocks AuthService.GetLoginInfoAsync() to return a LoginInfo object
- Uses a wrapper class that calls the real ExecuteAsync method but overrides the IsLoggedIn() method by shadowing it with a new method returning true or false.

Since IsLoggedIn() is static, I cannot override it, but I can create a wrapper class with a new method IsLoggedIn() and call that from ExecuteAsync. But ExecuteAsync calls AuthService.IsLoggedIn() directly, so no seam.

Therefore, I will write tests that call ExecuteAsync and verify the Logger calls by mocking ILogger and AuthService.GetLoginInfoAsync(), but I will not be able to test the IsLoggedIn() false branch without creating or deleting the file checked by IsLoggedIn().

I will write tests for the successful login info logging and the null login info error logging.

